class TypingGame:
    def __init__(self, target):
        self.target = target
        self.position = 0
        self.mistakes = 0

    def type_char(self, char):
        expected = self.target[self.position]
        if char == expected:
            self.position += 1
            return True
        self.mistakes += 1
        return False

    def completed(self):
        return self.position == len(self.target)

game = TypingGame("code")
for char in "code":
    game.type_char(char)

print(game.completed(), game.mistakes)
